/** A Tabler icon: 24-unit grid, 2-unit round strokes; a `true` path is filled instead. */
private fun tabler(name: String, autoMirror: Boolean, vararg paths: Pair<String, Boolean>): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f, autoMirror = autoMirror).apply {
        paths.forEach { (d, filled) ->
            if (filled) addPath(addPathNodes(d), fill = SolidColor(Color.Black))
            else addPath(
                addPathNodes(d), fill = null, stroke = SolidColor(Color.Black), strokeLineWidth = 2f,
                strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
            )
        }
    }.build()

/** A Fluent 2 icon: 24-unit grid, filled shapes. */
private fun fluent(name: String, autoMirror: Boolean, vararg paths: Pair<String, Boolean>): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f, autoMirror = autoMirror).apply {
        paths.forEach { (d, _) -> addPath(addPathNodes(d), fill = SolidColor(Color.Black)) }
    }.build()

/** A Material Symbols icon: 960-unit grid whose y runs from -960 to 0. */
private fun material(name: String, autoMirror: Boolean, vararg paths: Pair<String, Boolean>): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f, autoMirror = autoMirror).apply {
        addGroup(translationY = 960f)
        paths.forEach { (d, _) -> addPath(addPathNodes(d), fill = SolidColor(Color.Black)) }
        clearGroup()
    }.build()
